app.controller("Musician",function($scope,$http){$scope.fullScreen=!1,$scope.imgName="/field_small.jpg",$scope.placeholderImage="/field_small.jpg",$scope.loadPlaceholderImage=function(){$http({method:"POST",url:"/ajax",data:{command:"get_user_settings"}}).then(function(respond){respond.data&&respond.data.placeholder_image?$scope.placeholderImage=respond.data.placeholder_image:$scope.placeholderImage="/field_small.jpg"},function(erespond){$scope.placeholderImage="/field_small.jpg"})},$scope.checkNotes=function(){$http({method:"POST",url:"/ajax",data:{command:"get_notes"}}).then(function(respond){var imagePath=respond.data&&respond.data.image||"";$scope.imgName=imagePath?imagePath+"?t="+(new Date).getTime():$scope.placeholderImage})},$scope.toggleFullscreen=function(){$scope.fullScreen?document.exitFullscreen&&(document.exitFullscreen(),$scope.fullScreen=!1):(document.getElementById("img0").requestFullscreen(),$scope.fullScreen=!0)},$scope.loadPlaceholderImage(),$scope.checkNotes(),window.createAuthenticatedWebSocket(null,function(data){"notes_update"===data.type&&$scope.$apply(function(){$scope.checkNotes()})},null,function(connected){connected&&$scope.$applyAsync(function(){$scope.checkNotes()})})});